--region import
---@type OverseaStoreMgr
local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
--endregion import

--region define
local TimerModule = CS.Engine.Modules.TimerModule
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaMall/OverseaMallEventSpecialDialog.prefab > name: OverseaMallEventSpecialDialog
---@class OverseaStoreTimeLimitNode
---@field Env                           	OverseaStoreTimeLimitNode               
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field BG                            	UnityEngine.RectTransform               
---@field ScrollView                    	SuperScrollView.LoopListView2               
---@field Right                         	UnityEngine.RectTransform               
local OverseaStoreTimeLimitNode = Class("OverseaStoreTimeLimitNode")

--region lifecycle
function OverseaStoreTimeLimitNode:__init()
    self._storeType      = nil
    self._storeData      = {}
end

function OverseaStoreTimeLimitNode:__delete()
    self._storeType      = nil
    self._storeData      = nil
end

function OverseaStoreTimeLimitNode:Awake()
    self:InitHandler()
end

function OverseaStoreTimeLimitNode:Start()
    
end

function OverseaStoreTimeLimitNode:OnDestroy()
    self:StopTimer()
    self:RecordNewState()
    Events.RemoveListener(Constants.EventNames.OVERSEA_STORE_REFRESH, self._refreshEvent)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function OverseaStoreTimeLimitNode:InitHandler()
    self._refreshEvent = Events.AddListener(Constants.EventNames.OVERSEA_STORE_REFRESH, Bind(self, self.RefreshEventHandler))
end

function OverseaStoreTimeLimitNode:InitData()
    local storeData = clone(OverseaStoreMgr:GetStoreDataByType(self:GetStoreType()))
    self:SetStoreData(storeData)
    self:SortProducts()
    self:StartTimer()
    if storeData.nextRefreshLeftSeconds then
        self:RefreshCountdown()
    end
    CfUtils.SetActive(self.TimerGroup, storeData.nextRefreshLeftSeconds and true or false)
end
--endregion init

--region handler
---列表刷新
function OverseaStoreTimeLimitNode:OnGetItemByIndex(listView, index)
    if index < 0 then return nil end
    local cell = listView:NewListViewItem("OverseaMallEventSpecialNode")

    local cellData = self:GetProducts()[index + 1]
    local scr = CfUtils.GetLuaScr(cell, OverseaStoreConstants.ScrPath.OverseaStoreTimeLimitCell)
    if scr then
        scr:RefreshCell(self:GetStoreType(), cellData)
    end
    return cell
end

---定时器更新
function OverseaStoreTimeLimitNode:OnUpdate()
    if self:GetRefreshSeconds() then
        self:RefreshCountdown()
        if tonumber(self:GetRefreshSeconds()) <= 0 then
            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_HOME_REFRESH)
        end
    end

    for i, v in ipairs(self:GetProducts()) do
        local go = self.ScrollView:GetShownItemByItemIndex(i - 1)
        if not isNull(go) then
            local scr = CfUtils.GetLuaScr(go, OverseaStoreConstants.ScrPath.OverseaStoreTimeLimitCell)
            scr:UpdateTimeGroupText(v)
        end
    end

end

---刷新事件回调
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreTimeLimitNode:RefreshEventHandler(storeType)
    if storeType ~= self:GetStoreType() then return end
    self:RefreshUI()
end
--endregion handler

--region public
---刷新
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreTimeLimitNode:Refresh(storeType)
    self:SetStoreType(storeType)
    self:RefreshUI()
end

---刷新货币栏
function OverseaStoreTimeLimitNode:RefreshCurrencyBar()
    local currencyList = {Constants.Currency.FreeDiamondId}
    if OverseaStoreMgr:IsSecondaryCurrencyEnable() then
        table.insert(currencyList, 1, Constants.Currency.PayDiamondId)
    end
    CfUtils.RefreshTopGoods(currencyList)
end
--endregion public

--region private
---刷新UI
function OverseaStoreTimeLimitNode:RefreshUI()
    self:InitData()
    self:RefreshListView()
end

---刷新列表
function OverseaStoreTimeLimitNode:RefreshListView()
    local storeData = self:GetProducts()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#storeData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #storeData)
        self.ScrollView:MovePanelToItemIndex(0)
    end
end

---商品排序
function OverseaStoreTimeLimitNode:SortProducts()
    local storeData = self:GetProducts()
    table.sort(storeData, function (a, b)
        local sellOutA = checkInt(a.currentStock) == 0
        local sellOutB = checkInt(b.currentStock) == 0
        if sellOutA ~= sellOutB then
            return not sellOutA
        else
            return checkInt(a.pos) > checkInt(b.pos)
        end
    end)
end

---开启定时器
function OverseaStoreTimeLimitNode:StartTimer()
    TimerModule.Instance:AddTimer(self:GetTimerName(), 0, 1, Bind(self, self.OnUpdate))
end

---停止定时器
function OverseaStoreTimeLimitNode:StopTimer()
    TimerModule.Instance:RemoveTimer(self:GetTimerName())
end

---记录new状态
function OverseaStoreTimeLimitNode:RecordNewState()
    for _, v in ipairs(self:GetProducts()) do
        if OverseaStoreMgr:CheckTimeLimitGiftNew(v) then
            local key = OverseaStoreMgr:GetTimeLimitGiftNewSymbolKey(v)
            CfUtils.WriteLocalData(key, 1)
        end
    end
end

---刷新倒计时
function OverseaStoreTimeLimitNode:RefreshCountdown()
    local seconds = checkInt(self:GetRefreshSeconds())
    if seconds > 0 then
        local text = CfUtils.GetTimeHMS4(seconds)
        CfUtils.FillText(self.RefreshTimer, text)
    end
end

--endregion private

--region get / set
---设置商店类型
function OverseaStoreTimeLimitNode:SetStoreType(storeType)
    self._storeType = tostring(storeType)
end

---获取商店类型
function OverseaStoreTimeLimitNode:GetStoreType()
    return self._storeType
end

---设置充值数据
function OverseaStoreTimeLimitNode:SetStoreData(storeData)
    self._storeData = checkTable(storeData)
end

---获取充值数据
function OverseaStoreTimeLimitNode:GetStoreData()
    return self._storeData
end

---获取刷新时间
function OverseaStoreTimeLimitNode:GetRefreshSeconds()
    return self:GetStoreData().nextRefreshLeftSeconds
end

---获取商品列表
function OverseaStoreTimeLimitNode:GetProducts()
    return checkTable(self:GetStoreData().products)
end

---获取定时器名称
function OverseaStoreTimeLimitNode:GetTimerName()
    return Constants.TimerName.OverseaStoreTimeLimitNodeTimer .. self._storeType
end

--endregion get / set

return OverseaStoreTimeLimitNode